
const TCMS_INPUT = ['TEC-03','TEC-12','EVID_TEST_AUTHORIZATION'];
const TCMS_OUT = ['EVID_TCMS_SESSION','TEC-13'];
const TCMS_ROLES = [
  ['early','Wczesne zgłoszenie pomiarowe (ruch)'],
  ['auth','Autoryzowane otwarcie sesji diagnostycznej'],
  ['phase','Przejście do fazy prób'],
  ['warn','Ostrzeżenie wymagające rozstrzygnięcia'],
  ['close','Zamknięcie sesji']
];
const TCMS_ANS = Object.fromEntries(TCMS_LOGS.filter(r=>r.kind && ['early','auth','phase','warn','close','bridge'].includes(r.kind)).map(r=>[r.kind,r.id]));
const TCMS_DEFAULT=()=>({bookmarks:[],report:null,solved:false,attempts:0,filters:{},selected:''});
STATE.tcms=TCMS_DEFAULT();
function tcmsAvailable(){return TCMS_INPUT.filter(id=>STATE.found.has(id)).length>=2;}
function tcmsFiltered(){const f=STATE.tcms.filters||{};
return TCMS_LOGS.filter(r=>
 (!f.vehicle||r.vehicle===f.vehicle)&&(!f.day||r.date===f.day)&&(!f.session||norm(r.session).includes(norm(f.session)))&&
 (!f.code||norm(r.code).includes(norm(f.code)))&&(!f.mode||r.mode===f.mode)&&
 (!f.status||r.status===f.status)&&(!f.quality||r.quality===f.quality)&&
 ((!f.from&&!f.to)||(f.from&&f.to&&f.from>f.to?(r.time>=f.from||r.time<=f.to):(!f.from||r.time>=f.from)&&(!f.to||r.time<=f.to)))&&
 (!f.text||norm([r.id,r.detail,r.source,r.ref,r.code].join(' ')).includes(norm(f.text)))
 );}
function tcmsReportValue(){const fields={};for(const [role] of TCMS_ROLES) fields[role]=$('tcmsSlot_'+role)?.value||'';
fields.session=($('tcmsSession')?.value||'').trim().toUpperCase().replace(/\s+/g,'');
fields.earlyClass=$('tcmsEarlyClass')?.value||'';
fields.warningClass=$('tcmsWarningClass')?.value||'';
fields.sourceClass=$('tcmsSourceClass')?.value||'';
fields.gap=($('tcmsGap')?.value||'').trim();
fields.sourceDoc=$('tcmsSourceDoc')?.value||'';
return fields;}
function tcmsVerify(report,availableDocs){if(!report||typeof report!=='object')return false;
if(TCMS_ROLES.some(([role])=>report[role]!==TCMS_ANS[role]))return false;
if(report.session!=='DIAG-217/N'||report.earlyClass!=='diagnostic'||report.warningClass!=='controlled'||report.sourceClass!=='external')return false;
if(!/^0?19:51$/.test(String(report.gap||'')))return false;
if(report.sourceDoc!=='TEC-14'||!availableDocs.has('TEC-14'))return false;
if(!TCMS_INPUT.every(id=>availableDocs.has(id)))return false;
return true;}
function tcmsSetInputs(){
const root=$('tcmsWorkspace');
if(!root)return;
const docList=TCMS_INPUT.map(id=>`<span class="tcms-pill ${STATE.found.has(id)?'have':'missing'}">${esc(docName(id))} · ${STATE.found.has(id)?'uzyskano':'do odnalezienia'}</span>`).join('');
root.innerHTML=`<div class="tcms-intro"><div class="eyebrow">DIAGNOSTYKA TRAMWAJU TW-217</div>
<h3 style="margin:9px 0">Surowe logi TCMS</h3>
<p>W archiwum zachowano surowe pakiety kilku pojazdów, różnych sesji i retransmisje. Przeanalizuj wpisy bez założenia, że każdy alarm wskazuje rzeczywisty ruch tramwaju. Oceniaj <b>tryb, źródło, sesję i jakość zapisu</b>; pojedynczy komunikat nie rozstrzyga przyczyny śmierci.</p>
<div class="tcms-docline">${docList}</div>
${tcmsAvailable()?'':`<div class="notice warning" style="margin:14px 0">Aby rozpocząć analizę, znajdź co najmniej dwa materiały związane z diagnostyką TW-217. Sprawdź ewidencję techniczną i dokumentację sesji.</div>`}
</div><div id="tcmsWorkbench"></div>`;
if(!tcmsAvailable())return;
$('tcmsWorkbench').innerHTML=`<div class="tcms-head"><div><b>MAGISTRALA / EKSPORT SUROWY</b><div class="muted small">${TCMS_LOGS.length} pakiety · 17/18.11.2026 · czasy lokalne</div></div><div class="formline"><button class="btn alt" id="tcmsExport">Eksport bieżącego widoku CSV</button><button class="btn subtle" id="tcmsClear">Wyczyść filtry</button></div></div>
<div class="tcms-filter-grid">
<label>Dzień<select id="tcmsDay"><option value="">Oba dni</option><option value="17.11.2026">17 listopada</option><option value="18.11.2026">18 listopada</option></select></label>
<label>Pojazd<select id="tcmsVehicle"><option value="">Wszystkie</option>${['TW-217','TW-213','TW-224','HOST'].map(v=>`<option>${v}</option>`).join('')}</select></label>
<label>Sesja<input class="input" id="tcmsSessionFilter" placeholder="fragment identyfikatora"></label>
<label>Kod<input class="input" id="tcmsCodeFilter" placeholder="np. nazwa zdarzenia"></label>
<label>Tryb<select id="tcmsMode"><option value="">Dowolny</option>${['RUCH','NORMAL','SERWIS','TEST','SIEĆ'].map(v=>`<option>${v}</option>`).join('')}</select></label>
<label>Status<select id="tcmsStatus"><option value="">Dowolny</option>${['OK','WARN','INFO','RETRY'].map(v=>`<option>${v}</option>`).join('')}</select></label>
<label>Jakość<select id="tcmsQuality"><option value="">Dowolna</option>${['PRIMARY','RETRY'].map(v=>`<option>${v}</option>`).join('')}</select></label>
<label>Od (HH:MM:SS)<input id="tcmsFrom" class="input mono" placeholder="00:00:00" maxlength="8"></label>
<label>Do (HH:MM:SS)<input id="tcmsTo" class="input mono" placeholder="23:59:59" maxlength="8"></label>
<label>Szukaj w wierszach<input id="tcmsText" class="input" placeholder="źródło, opis, kod, pakiet"></label>
</div>
<div class="tcms-table-box"><div id="tcmsStats" class="small muted" style="padding:10px 13px"></div><div class="tcms-scroll"><table class="tcms-table"><thead><tr><th>Znacznik</th><th>Pojazd</th><th>Sesja</th><th>Tryb</th><th>Kod / status</th><th>Jakość</th><th>Pakiet</th></tr></thead><tbody id="tcmsRows"></tbody></table></div><div class="formline tcms-pager"><button class="btn alt" id="tcmsPrev">Wstecz</button><span class="small muted" id="tcmsPageInfo"></span><button class="btn alt" id="tcmsNext">Dalej</button></div></div>
<div class="tcms-bottom"><div class="surface padded"><div class="eyebrow">INSPEKTOR PAKIETÓW</div><div id="tcmsDetail" class="tcms-detail muted">Wybierz pakiet w tabeli. Możesz dodać go do rejestru obserwacji.</div><button class="btn alt" id="tcmsBookmark" disabled>Przypnij wybrany pakiet</button></div><div class="surface padded"><div class="eyebrow">REJESTR OBSERWACJI</div><div id="tcmsBookmarks" class="tcms-bookmarks"></div></div></div>
<div class="surface padded tcms-report"><div class="eyebrow">RAPORT ANALITYCZNY / ODTWORZENIE CIĄGU ZDARZEŃ</div><h3 style="margin:9px 0">Zestaw weryfikowalną sekwencję</h3><p class="muted small">Używaj wyłącznie pakietów, które samodzielnie oznaczyłeś w inspektorze. Każda pozycja musi pochodzić z właściwej sesji, trybu i daty. Powtórzenia oznaczone RETRY nie są nowymi zdarzeniami.</p>
<div class="tcms-roles">${TCMS_ROLES.map(([id,name])=>`<label>${esc(name)}<select id="tcmsSlot_${id}" class="tcmsSlot"><option value="">Wybierz z przypiętych pakietów</option></select></label>`).join('')}</div>
<div class="tcms-logic">
<label>Identyfikator badanej sesji<input class="input mono" id="tcmsSession" placeholder="identyfikator z rejestru"></label>
<label>Znaczenie wczesnego ostrzeżenia<select id="tcmsEarlyClass"><option value="">Wybierz interpretację</option><option value="sabotage">Potwierdzony sabotaż</option><option value="diagnostic">Wskazanie wymagające diagnostyki</option><option value="irrelevant">Bez znaczenia technicznego</option></select></label>
<label>Status ostrzeżenia podczas sesji<select id="tcmsWarningClass"><option value="">Wybierz interpretację</option><option value="accident">Samoczynny ruch wagonu</option><option value="controlled">Sygnał w kontrolowanej próbie</option><option value="tamper">Nieautoryzowana modyfikacja</option></select></label>
<label>Źródło zdarzenia o 01:44<select id="tcmsSourceClass"><option value="">Wybierz źródło</option><option value="vehicle">Sterownik ruchu pojazdu</option><option value="external">Niezależny czujnik infrastruktury</option><option value="unsure">Niemożliwe do ustalenia z akt</option></select></label>
<label>Czas od zamknięcia badanej sesji do 01:44:00 (mm:ss)<input class="input mono" id="tcmsGap" placeholder="mm:ss" maxlength="7"></label>
<label>Dokument niezależnego źródła<select id="tcmsSourceDoc"><option value="">Wybierz zdobyty materiał</option>${DOCS.filter(d=>STATE.found.has(d.id)).map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select></label></div>
<div class="formline" style="margin-top:18px"><button class="btn" id="tcmsSubmit">Zweryfikuj raport</button><span id="tcmsReportStatus" class="muted small" role="status" aria-live="polite"></span></div><div id="tcmsSolvedNote" class="notice" style="display:none;margin-top:14px"></div></div>`;
$('tcmsPrev').addEventListener('click',()=>{tcmsPage=Math.max(0,tcmsPage-1);tcmsRenderRows();});
$('tcmsNext').addEventListener('click',()=>{tcmsPage++;tcmsRenderRows();});
$('tcmsExport').addEventListener('click',tcmsCSV);
$('tcmsClear').addEventListener('click',()=>{for(const k of Object.keys(TCMS_FILTER_INPUT))$(TCMS_FILTER_INPUT[k]).value='';STATE.tcms.filters={};tcmsPage=0;tcmsRenderRows();});
for(const [key,id] of Object.entries(TCMS_FILTER_INPUT)){$(id).value=STATE.tcms.filters?.[key]||'';$(id).addEventListener('input',()=>{STATE.tcms.filters[key]=$(id).value;tcmsPage=0;tcmsRenderRows();});}
$('tcmsBookmark').addEventListener('click',tcmsToggleBookmark);
$('tcmsSubmit').addEventListener('click',tcmsSubmit);
for(const control of $('tcmsWorkbench').querySelectorAll('.tcmsSlot,#tcmsSession,#tcmsEarlyClass,#tcmsWarningClass,#tcmsSourceClass,#tcmsGap,#tcmsSourceDoc')){control.addEventListener('change',()=>{STATE.tcms.report=tcmsReportValue();});control.addEventListener('input',()=>{STATE.tcms.report=tcmsReportValue();});}
tcmsPage=0;tcmsRenderRows();tcmsRenderBookmarks();
if(STATE.tcms.solved)tcmsShowResult();}
const TCMS_FILTER_INPUT={day:'tcmsDay',vehicle:'tcmsVehicle',session:'tcmsSessionFilter',code:'tcmsCodeFilter',mode:'tcmsMode',status:'tcmsStatus',quality:'tcmsQuality',from:'tcmsFrom',to:'tcmsTo',text:'tcmsText'};
let tcmsPage=0;
function tcmsRenderRows(){const rows=tcmsFiltered(),max=Math.max(0,Math.ceil(rows.length/45)-1);tcmsPage=Math.min(tcmsPage,max);
$('tcmsStats').textContent=`Widok: ${rows.length} / ${TCMS_LOGS.length} pakietów. Wyświetlane: ${Math.min(rows.length,45)} · sortowanie chronologiczne.`;
$('tcmsRows').innerHTML=rows.slice(tcmsPage*45,(tcmsPage+1)*45).map(r=>`<tr class="${r.id===STATE.tcms.selected?'picked':''} ${r.status==='WARN'?'warn':''}" data-tcms-row="${r.id}"><td class="mono">${r.date}<br>${r.time}</td><td>${r.vehicle}</td><td class="mono">${esc(r.session)}</td><td>${esc(r.mode)}</td><td class="mono">${esc(r.code)}<small>${esc(r.status)}</small></td><td>${esc(r.quality)}</td><td>${r.id}</td></tr>`).join('')||'<tr><td colspan="7">Brak pakietów dla bieżących filtrów.</td></tr>';
$('tcmsRows').querySelectorAll('[data-tcms-row]').forEach(el=>el.addEventListener('click',()=>tcmsChoose(el.dataset.tcmsRow)));
$('tcmsPageInfo').textContent=`Strona ${tcmsPage+1} / ${max+1}`;$('tcmsPrev').disabled=tcmsPage===0;$('tcmsNext').disabled=tcmsPage===max;
const r=TCMS_LOGS.find(x=>x.id===STATE.tcms.selected);if(r)tcmsShowDetail(r);}
function tcmsChoose(id){STATE.tcms.selected=id;const r=TCMS_LOGS.find(x=>x.id===id);if(r)tcmsShowDetail(r);tcmsRenderRows();}
function tcmsShowDetail(r){$('tcmsDetail').innerHTML=`<b class="mono">${esc(r.id)} / ${esc(r.date)} ${esc(r.time)}</b><div class="small" style="margin-top:9px">${esc(r.vehicle)} · ${esc(r.source)} · ${esc(r.session)} · ${esc(r.mode)} / ${esc(r.status)}</div><div style="margin-top:9px">${esc(r.detail)}</div><div class="small muted">Kwalifikator: ${r.quality}${r.ref?' · odniesienie: '+esc(r.ref):''}</div>`;$('tcmsBookmark').disabled=false;$('tcmsBookmark').textContent=STATE.tcms.bookmarks.includes(r.id)?'Odepnij pakiet':'Przypnij pakiet';}
function tcmsToggleBookmark(){const id=STATE.tcms.selected;if(!id)return;const i=STATE.tcms.bookmarks.indexOf(id);if(i>=0)STATE.tcms.bookmarks.splice(i,1);else if(STATE.tcms.bookmarks.length<30)STATE.tcms.bookmarks.push(id);else {toast('Rejestr mieści 30 pakietów. Odrzuć mniej istotne obserwacje.');return;}tcmsRenderBookmarks();tcmsRenderRows();}
function tcmsRenderBookmarks(){const book=STATE.tcms.bookmarks.map(id=>TCMS_LOGS.find(r=>r.id===id)).filter(Boolean);$('tcmsBookmarks').innerHTML=book.length?book.map(r=>`<div class="tcms-bookrow"><button class="tcms-link" data-tcms-jump="${r.id}">${r.id} · ${r.time} · ${esc(r.code)} (${esc(r.mode)})</button><button class="btn subtle" data-tcms-unpin="${r.id}" aria-label="Odepnij ${r.id}">×</button></div>`).join(''):'<p class="muted small" style="padding:10px 0">Nie przypięto jeszcze żadnego pakietu.</p>';
$('tcmsBookmarks').querySelectorAll('[data-tcms-jump]').forEach(b=>b.addEventListener('click',()=>tcmsChoose(b.dataset.tcmsJump)));
$('tcmsBookmarks').querySelectorAll('[data-tcms-unpin]').forEach(b=>b.addEventListener('click',()=>{STATE.tcms.bookmarks=STATE.tcms.bookmarks.filter(x=>x!==b.dataset.tcmsUnpin);tcmsRenderBookmarks();tcmsRenderRows();}));
for(const [id] of TCMS_ROLES){let s=$('tcmsSlot_'+id),was=s.value;s.innerHTML='<option value="">Wybierz z przypiętych pakietów</option>'+book.map(r=>`<option value="${r.id}">${r.id} / ${r.date} ${r.time} / ${esc(r.code)} · ${esc(r.mode)}</option>`).join('');if(book.some(r=>r.id===was))s.value=was;}
if(STATE.tcms.report){const f=STATE.tcms.report;for(const [id] of TCMS_ROLES){let s=$('tcmsSlot_'+id);if(book.some(r=>r.id===f[id]))s.value=f[id];}
for(const [name,id] of Object.entries({session:'tcmsSession',earlyClass:'tcmsEarlyClass',warningClass:'tcmsWarningClass',sourceClass:'tcmsSourceClass',gap:'tcmsGap',sourceDoc:'tcmsSourceDoc'})){if(f[name]!=null&&$(id))$(id).value=f[name];}
}}
function tcmsCSV(){const rows=tcmsFiltered();const keys=['id','date','time','vehicle','source','session','mode','code','status','quality','ref','detail'];const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\ufeff'+keys.join(';')+'\r\n'+rows.map(r=>keys.map(k=>q(r[k])).join(';')).join('\r\n');const b=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='TCMS_widok_surowych_pakietow.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000);}
function tcmsSubmit(){const r=tcmsReportValue();STATE.tcms.report=r;STATE.tcms.attempts++;
const problems=[];
if(TCMS_ROLES.some(([id])=>!r[id]))problems.push('Brak przypisania jednego lub kilku pakietów do sekwencji.');
if(!r.session||!r.earlyClass||!r.warningClass||!r.sourceClass||!r.gap||!r.sourceDoc)problems.push('Raport nie zawiera wszystkich interpretacji i powiązań źródłowych.');
if(!TCMS_INPUT.every(id=>STATE.found.has(id)))problems.push('Nie zweryfikowano kompletnego zestawu dokumentów wejściowych: zapis, indeks pakietów i autoryzacja.');
if(!STATE.found.has('TEC-14'))problems.push('Brak niezależnego źródła dla zdarzenia poza pojazdem.');
if(!problems.length&&!tcmsVerify(r,STATE.found))problems.push('Nie można przyjąć chronologii lub interpretacji: przynajmniej jeden rekord nie zgadza się z udokumentowaną sesją, trybem, odstępem czasu albo źródłem. Sprawdź retransmisje i zapisy z innych pojazdów.');
if(problems.length){$('tcmsReportStatus').textContent=`Raport niezweryfikowany (próba ${STATE.tcms.attempts}).`;$('tcmsSolvedNote').style.display='block';$('tcmsSolvedNote').classList.add('warning');$('tcmsSolvedNote').textContent=problems.join(' ');return;}
STATE.tcms.solved=true;for(const id of TCMS_OUT)STATE.found.add(id);PS_EVENTS.laboratory('tcms',TCMS_OUT);tcmsShowResult();renderDocs();renderAttached();toast('Zweryfikowano analizę TCMS. Dwa nowe materiały dołączono do akt.');}
function tcmsShowResult(){const el=$('tcmsSolvedNote');if(!el)return;el.style.display='block';el.classList.remove('warning');el.innerHTML='<b>Analiza ukończona i udokumentowana.</b> Dołączono do akt surową sekwencję sesji oraz protokół jej zamknięcia. Sam wynik nie wskazuje sprawcy ani mechanizmu śmierci; wymaga zestawienia z odrębnymi źródłami.';$('tcmsReportStatus').textContent='Status: analiza zatwierdzona';$('tcmsSubmit').disabled=true;}
function tcmsRestore(saved){const state=TCMS_DEFAULT();if(saved&&typeof saved==='object'){
state.bookmarks=Array.isArray(saved.bookmarks)?[...new Set(saved.bookmarks.filter(x=>typeof x==='string'&&TCMS_LOGS.some(r=>r.id===x)))].slice(0,30):[];
state.report=saved.report&&typeof saved.report==='object'?saved.report:null;
state.attempts=Number.isInteger(saved.attempts)?Math.max(0,Math.min(10000,saved.attempts)):0;
state.filters=(saved.filters&&typeof saved.filters==='object')?Object.fromEntries(Object.entries(saved.filters).filter(([k,v])=>k in TCMS_FILTER_INPUT&&typeof v==='string').map(([k,v])=>[k,v.slice(0,100)])):{};
state.solved=!!(state.report&&TCMS_ROLES.every(([role])=>state.bookmarks.includes(state.report[role]))&&tcmsVerify(state.report,STATE.found));
if(state.solved)for(const id of TCMS_OUT)STATE.found.add(id);
}STATE.tcms=state;}
function tcmsReset(){STATE.tcms=TCMS_DEFAULT();TCMS_OUT.forEach(id=>STATE.found.delete(id));if($('tcmsWorkspace'))tcmsSetInputs();}
