function mini5Select(kind,id,value){
 const options=MINI5_REPORTS[kind]||[];
 return `<fieldset class="mini5-field"><legend>Najlepiej uzasadniony wniosek — wybierz jedną z pięciu możliwości</legend>
 <input type="hidden" id="${id}" value="${esc(value)}">
 <div class="mini5-options">${options.map(([code,label],i)=>`<label class="mini5-choice"><input type="radio" name="${id}-choice" data-mini5-radio="${id}" value="m5:${code}" ${value===`m5:${code}`?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(label)}</span></label>`).join('')}</div></fieldset>`;
}
document.addEventListener('change',e=>{
 const radio=e.target.closest?.('[data-mini5-radio]');if(!radio||!radio.checked)return;
 const field=document.getElementById(radio.dataset.mini5Radio);if(!field)return;
 field.value=radio.value;field.dispatchEvent(new Event('input',{bubbles:true}));
});
function mini5Correct(kind,answer){
 const codes={msg:'integrity',cctv:'bounded',forensic:'bounded',access:'bounded'};
 return answer===`m5:${codes[kind]}`;
}

function msgReportRead(){const r={};for(const k of ['slot','time','account','device','source','summary'])r[k]=String($('msgR_'+k)?.value||'').trim().slice(0,800);return r;}
function msgIsValid(saved,found){if(!saved||!Array.isArray(saved.chain)||saved.chain.length!==5||!MSG_INPUT.every(id=>found.has(id)))return false;
 if(saved.chain.some((id,i)=>id!==MSG_ANSWER.ids[i]))return false;
 const bytes=msgKeyBytes(saved.key);if(!bytes||saved.chain.some(id=>!msgDecode(MSG_BY_ID[id],saved.key).valid))return false;
 const r=saved.report||{};
 const n=x=>norm(String(x||'')).replace(/[^a-z0-9]/g,'');
 if(n(r.slot)!=='4107'||n(r.time)!=='0132'||n(r.account)!=='aud04'||n(r.device)!=='tabaud02'||n(r.source)!=='dig05')return false;
 const summary=norm(r.summary||'').replace(/[^a-z0-9ąćęłńóśźż ]/g,' ');
 const requirements=[/oryginal|protokol/,/stanowisk/,/oznacze|porown|porownan/];
 if(String(r.summary||'').startsWith('m5:'))return mini5Correct('msg',r.summary);
  if(summary.length<55||!requirements.every(re=>re.test(summary)))return false;
 return true;
}
function msgSetResult(){for(const id of MSG_OUTPUT)STATE.found.add(id);STATE.msg.solved=true;PS_EVENTS.laboratory('messages',MSG_OUTPUT);renderDocs();renderAttached();if($('msgPanel')&&!$('msgPanel').hidden)msgRender();tcmsRefresh();toast('Raport korespondencji zweryfikowany. Dwa materiały trafiły do akt.');}
function msgVerifySubmit(){STATE.msg.report=msgReportRead();STATE.msg.attempts++;
 const note=$('msgReportNote');if(!msgIsValid(STATE.msg,STATE.found)){
 const parts=[];if(!MSG_INPUT.every(x=>STATE.found.has(x)))parts.push('Brakuje niezależnych dokumentów źródłowych.');
 if(STATE.msg.chain.length!==5)parts.push('Zapisana sekwencja nie obejmuje wymaganych pięciu bloków.');
 if(STATE.msg.chain.some(x=>!msgDecode(MSG_BY_ID[x],STATE.msg.key).valid))parts.push('W łańcuchu znajdują się bloki bez poprawnej weryfikacji dekodowania.');
 if(!parts.length)parts.push('Raport nie uzgadnia łańcucha bloków, przypisania źródłowego i treści. Ponownie porównaj wskaźniki prev/next, slot, urządzenie i zachowane metadane.');
 note.className='notice warning';note.textContent='Nie można zatwierdzić rekonstrukcji. '+parts.join(' ');note.scrollIntoView({behavior:'smooth',block:'nearest'});return;
 }STATE.msg.solved=true;msgSetResult();}
function msgRender(){const root=$('msgWorkspace');if(!root)return;const st=STATE.msg;const badges=MSG_INPUT.map(id=>`<span class="tcms-pill ${STATE.found.has(id)?'have':'missing'}">${esc(docName(id))} · ${STATE.found.has(id)?'uzyskano':'do odnalezienia'}</span>`).join('');
 root.innerHTML=`<div class="msg-intro"><div class="eyebrow">ANALIZA KORESPONDENCJI</div><h3>Archiwum fragmentów wiadomości</h3><p>Odczyt zabezpieczonej kopii przechowuje zaszyfrowane fragmenty, uszkodzone indeksy i kilka wątków o podobnych aliasach. Zrekonstruuj <b>jedną rzeczywistą wiadomość</b> na podstawie wskaźników bloków i niezależnych metadanych. Alias nadawcy nie stanowi identyfikacji człowieka.</p><div class="tcms-docline">${badges}</div><p class="muted small">Protokół rekordu: UTF-8, prefiks jawnego komunikatu <code>MSG|v2|</code>, cykliczny XOR z kluczem trzech bajtów HEX, CRC-16/CCITT na tekście <em>przed</em> szyfrowaniem. Klucz i kolejność należy odzyskać z danych; system nie wybierze właściwych bloków.</p></div><div id="msgBody"></div>`;
 if(!msgHasInputs()){ $('msgBody').innerHTML='<div class="notice warning">Najpierw pozyskaj przynajmniej dwa niezależne dokumenty wejściowe z archiwum cyfrowego (DIG-03, DIG-04, DIG-05). Wyniki nie będą dostępne przed analizą.</div>';return;}
 $('msgBody').innerHTML=`<div class="msg-flex-head"><div><b>Archiwum:</b> ${MSG_RECORDS.length} rekordów · filtrowanie bez wskazywania rozwiązania</div><button class="btn subtle" id="msgExportCsv">Eksportuj aktualny wykaz CSV</button></div>
 <div class="msg-filter-grid">
 <label>Slot indeksu <input id="msgF_slot" placeholder="numer slotu" value="${esc(st.filters.slot)}"></label>
 <label>Alias kontaktu <input id="msgF_alias" placeholder="alias" value="${esc(st.filters.alias)}"></label>
 <label>Identyfikator wątku <input id="msgF_thread" placeholder="thread" value="${esc(st.filters.thread)}"></label>
 <label>Identyfikator urządzenia <input id="msgF_device" placeholder="device" value="${esc(st.filters.device)}"></label>
 <label>Stan kopii <select id="msgF_quality"><option value="">Wszystkie</option>${['PRIMARY','PARTIAL','MIRROR'].map(x=>`<option ${st.filters.quality===x?'selected':''}>${x}</option>`).join('')}</select></label>
 <label>Status <select id="msgF_status"><option value="">Wszystkie</option>${['ACTIVE','DELETED','ORPHAN'].map(x=>`<option ${st.filters.status===x?'selected':''}>${x}</option>`).join('')}</select></label>
 <label style="grid-column:1/-1">Wyszukiwanie techniczne <input id="msgF_search" placeholder="ID, blok, wskaźnik prev/next, czas..." value="${esc(st.filters.search)}"></label>
 </div>
 <div class="msg-parts"><div class="msg-table-wrap"><table class="msg-table"><thead><tr><th>Nr rekordu / blok</th><th>Slot / wątek</th><th>Poprzedni → następny</th><th>Oznaczenie nadawcy</th><th>Urządzenie</th><th>Czas</th><th>Jakość</th></tr></thead><tbody id="msgTableRows"></tbody></table></div><div class="formline msg-page"><span id="msgCount"></span><button class="btn subtle" id="msgClearFilters">Wyczyść filtry</button></div></div>
 <div class="msg-grid-two"><div class="surface padded"><div class="eyebrow">INSPEKTOR BAJTÓW</div><h3 style="margin:8px 0">Wybrany rekord</h3><div id="msgInspect">Wybierz wiersz w tabeli.</div><label class="msg-key-label">Klucz XOR (3 bajty HEX) <input id="msgKey" value="${esc(st.key)}" placeholder="np. A1 B2 C3" autocomplete="off" spellcheck="false" maxlength="12"></label><button class="btn subtle" id="msgDecodeBtn">Odszyfruj wybrany blok i sprawdź CRC</button><div id="msgDecoded" class="msg-decode">Wpisz ustalony klucz i przetestuj fragment.</div></div><div class="surface padded"><div class="eyebrow">ODTWARZANA SEKWENCJA</div><h3 style="margin:8px 0">Łańcuch bloków</h3><p class="muted small">Dodawaj bloki z inspektora. Strzałkami ustal ich kolejność. Zwracaj uwagę na zgodność identyfikatora wątku i wzajemnych wskaźników.</p><div id="msgChain"></div><div class="msg-chain-preview" id="msgPreview"></div></div></div>
 <div class="surface padded msg-report"><div class="eyebrow">RAPORT ANALITYCZNY / REKONSTRUKCJA I PRZYPISANIE ŹRÓDŁA</div><h3>Protokół odzyskania wiadomości</h3><p class="muted small">Aby zatwierdzić materiał, odtwórz kolejność zaszyfrowanych bloków, wykaż spójność ich integralności i uzgodnij konto, urządzenie oraz czas z dokumentami, a nie z samymi inicjałami.</p><div class="msg-filter-grid msg-report-grid">${[
 ['slot','Numer slotu'],['time','Godzina nadania (HH:MM)'],['account','Identyfikator konta'],['device','Identyfikator urządzenia'],['source','Niezależny dokument metadanych']].map(([k,l])=>`<label>${l}<input id="msgR_${k}" value="${esc(st.report[k]||'')}" autocomplete="off"></label>`).join('')}<div class="msg-wide">${mini5Select('msg','msgR_summary',st.report.summary||'')}</div></div><div class="formline"><button class="btn" id="msgSubmit" ${st.solved?'disabled':''}>Zweryfikuj raport i łańcuch</button><span id="msgAttemptCounter" class="muted small">Próby weryfikacji: ${st.attempts}</span></div><div id="msgReportNote" class="notice ${st.solved?'':'warning'}">${st.solved?'Analiza zakończona: dwa niezależne materiały dołączono do akt. Sama korespondencja nie stanowi dowodu fizycznej obecności nadawcy.':'Wynik zostanie przyznany dopiero po udokumentowaniu poprawnej rekonstrukcji.'}</div></div>`;
 for(const k of ['slot','alias','thread','device','quality','status','search']){$('msgF_'+k).addEventListener('input',()=>{st.filters[k]=$('msgF_'+k).value;msgRenderRows();});}
 for(const k of ['slot','time','account','device','source','summary'])$('msgR_'+k).addEventListener('input',()=>{st.report[k]=$('msgR_'+k).value.slice(0,800);});
 $('msgKey').addEventListener('input',()=>{st.key=$('msgKey').value.slice(0,12);msgRenderChain();});
 $('msgDecodeBtn').addEventListener('click',msgShowDecoded);
 $('msgClearFilters').addEventListener('click',()=>{st.filters={slot:'',alias:'',thread:'',device:'',quality:'',status:'',search:''};msgRender();});
 $('msgSubmit').addEventListener('click',msgVerifySubmit);
 $('msgExportCsv').addEventListener('click',msgExportCsv);
 msgRenderRows();msgRenderInspect();msgRenderChain();}
function msgRenderRows(){const rows=msgFiltered();$('msgCount').textContent=`Wynik filtrowania: ${rows.length} z ${MSG_RECORDS.length}`;
 $('msgTableRows').innerHTML=rows.slice(0,250).map(r=>`<tr data-msg-row="${r.id}" class="${STATE.msg.selected===r.id?'msg-active':''}"><td><b>${r.id}</b><small>${esc(r.block)}</small></td><td>${esc(r.slot)}<small>${esc(r.thread)}</small></td><td>${esc(r.prev)} → ${esc(r.next)}</td><td>${esc(r.alias)}</td><td>${esc(r.device)}</td><td>${esc(r.time)}</td><td>${esc(r.quality)}</td></tr>`).join('');
 $('msgTableRows').querySelectorAll('[data-msg-row]').forEach(el=>el.addEventListener('click',()=>{STATE.msg.selected=el.dataset.msgRow;msgRenderRows();msgRenderInspect();}));}
function msgRenderInspect(){const el=$('msgInspect');if(!el)return;const r=MSG_BY_ID[STATE.msg.selected];if(!r){el.textContent='Wybierz rekord z tabeli.';return;}
 el.innerHTML=`<div class="msg-meta"><b>${r.id}</b> · blok ${esc(r.block)}<p>Slot: ${esc(r.slot)} · wątek: ${esc(r.thread)}</p><p>Wskaźnik: ${esc(r.prev)} → <b>${esc(r.block)}</b> → ${esc(r.next)}</p><p>Alias: ${esc(r.alias)} · konto: ${esc(r.account)} · urządzenie: ${esc(r.device)}</p><p>Znacznik: ${esc(r.time)} · status: ${esc(r.status)} · ${esc(r.origin)}/${esc(r.quality)}</p><p>CRC-16: <code>${esc(r.check)}</code></p><div class="msg-hex">${esc(r.payload.replace(/(.{2})/g,'$1 ').trim())}</div></div><button class="btn subtle" id="msgAddChain" ${STATE.msg.chain.includes(r.id)||STATE.msg.solved?'disabled':''}>Dodaj ten blok do rekonstrukcji</button>`;
 $('msgAddChain').addEventListener('click',()=>{if(STATE.msg.chain.includes(r.id)||STATE.msg.chain.length>=9)return;STATE.msg.chain.push(r.id);msgRenderInspect();msgRenderChain();});
 $('msgDecoded').textContent='Wybierz klucz i odszyfruj wybrany blok.';}
function msgShowDecoded(){const r=MSG_BY_ID[STATE.msg.selected];const decoded=msgDecode(r,STATE.msg.key);const el=$('msgDecoded');if(!r){el.textContent='Najpierw wybierz rekord.';return;}
 el.classList.toggle('msg-valid',decoded.valid);el.innerHTML=decoded.valid?`<b>Spójność CRC potwierdzona.</b><div class="msg-plain">${esc(decoded.text)}</div><small>Poprawne odszyfrowanie dowodzi integralności tego bloku, a nie przypisania autora.</small>`:`<b>Odczyt nieważny.</b> ${esc(decoded.reason)}`;}
function msgChainMove(i,delta){const arr=STATE.msg.chain;let other=i+delta;if(other<0||other>=arr.length)return;[arr[i],arr[other]]=[arr[other],arr[i]];msgRenderChain();}
function msgChainRemove(i){STATE.msg.chain.splice(i,1);msgRenderChain();msgRenderInspect();}
function msgRenderChain(){const el=$('msgChain');if(!el)return;
 el.innerHTML=STATE.msg.chain.length?STATE.msg.chain.map((id,i)=>{const r=MSG_BY_ID[id],decoded=msgDecode(r,STATE.msg.key);return `<div class="msg-chain-row"><span>${i+1}. <b>${esc(r.block)}</b> ${esc(id)}<small>${esc(r.prev)} → ${esc(r.next)} · ${decoded.valid?'CRC OK':'CRC ?'}</small></span><span><button class="btn subtle" data-shift="${i},-1" ${i===0||STATE.msg.solved?'disabled':''} aria-label="Przesuń w górę">↑</button><button class="btn subtle" data-shift="${i},1" ${i===STATE.msg.chain.length-1||STATE.msg.solved?'disabled':''} aria-label="Przesuń w dół">↓</button><button class="btn subtle" data-remove="${i}" ${STATE.msg.solved?'disabled':''} aria-label="Usuń">×</button></span></div>`;}).join(''):'<div class="muted small">Nie wybrano jeszcze żadnego bloku.</div>';
 el.querySelectorAll('[data-shift]').forEach(btn=>btn.addEventListener('click',()=>{let [i,d]=btn.dataset.shift.split(',').map(Number);msgChainMove(i,d);}));el.querySelectorAll('[data-remove]').forEach(btn=>btn.addEventListener('click',()=>msgChainRemove(Number(btn.dataset.remove))));
 const complete=STATE.msg.chain.length>0&&STATE.msg.chain.every(id=>msgDecode(MSG_BY_ID[id],STATE.msg.key).valid);
 $('msgPreview').innerHTML=complete?'<b>Odczyt wybranych fragmentów:</b><div class="msg-plain">'+esc(STATE.msg.chain.map(id=>msgDecode(MSG_BY_ID[id],STATE.msg.key).text).join(''))+'</div>':'Podgląd treści dostępny po weryfikacji poprawnego klucza dla wszystkich wybranych bloków.';}
function msgExportCsv(){const head=['id','block','slot','thread','prev','next','alias','account','device','time','quality','origin','status','payload','check'];let rows=[head,...msgFiltered().map(r=>head.map(h=>r[h]))];const val=v=>'"'+String(v||'').replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+rows.map(r=>r.map(val).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Baza_wiadomosci_odczyt_filtrowany.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000);}
function msgRestore(saved){const st=MSG_DEFAULT();if(saved&&typeof saved==='object'){
 if(saved.filters&&typeof saved.filters==='object')for(const k of Object.keys(st.filters))if(typeof saved.filters[k]==='string')st.filters[k]=saved.filters[k].slice(0,80);
 if(typeof saved.selected==='string'&&MSG_BY_ID[saved.selected])st.selected=saved.selected;
 if(typeof saved.key==='string')st.key=saved.key.slice(0,12);
 if(Array.isArray(saved.chain))st.chain=[...new Set(saved.chain.filter(id=>typeof id==='string'&&MSG_BY_ID[id]))].slice(0,9);
 if(saved.report&&typeof saved.report==='object')for(const k of Object.keys(st.report))if(typeof saved.report[k]==='string')st.report[k]=saved.report[k].slice(0,800);
 st.attempts=Number.isInteger(saved.attempts)?Math.max(0,Math.min(10000,saved.attempts)):0;
 st.solved=msgIsValid(st,STATE.found);
 if(st.solved)for(const id of MSG_OUTPUT)STATE.found.add(id);
 }STATE.msg=st;}
function msgReset(){STATE.msg=MSG_DEFAULT();for(const id of MSG_OUTPUT)STATE.found.delete(id);if($('msgWorkspace'))msgRender();}
function msgRefresh(){if($('msgPanel')&&!$('msgPanel').hidden)msgRender();}

